import{z as d,x as p,o as t,c as F,q as l,j as i,D as e,d as n,s,S as E,b as r}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"组合子与不动点","description":"","frontmatter":{"title":"组合子与不动点","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/combinators-fixed-point.md","filePath":"cs/combinators-fixed-point.md","lastUpdated":1791413859000}'),A={name:"cs/combinators-fixed-point.md"};function B(m,a,c,h,Y,f){const o=p("Mermaid");return t(),F("div",null,[a[2]||(a[2]=l('<h1 id="组合子与不动点" tabindex="-1">组合子与不动点 <a class="header-anchor" href="#组合子与不动点" aria-label="Permalink to &quot;组合子与不动点&quot;">​</a></h1><div class="epigraph"><p>$S$ 与 $K$ 生成全部 λ 项的组合子片段；$Y=\\lambda f.(\\lambda x.f(xx))(\\lambda x.f(xx))$ 给出不动点，递归不必「调用名字」。</p><footer>—— 据 Curry；Schönfinkel；Barendregt 整理</footer></div><p>上一课<a href="/cs/lambda-calculus">λ 演算</a>用变量绑定写函数，并留下递归。缺口是两件：<strong>组合子</strong>（无自由变量的项，甚至无绑定器的 \\(SK\\) 基底）与<strong>不动点组合子</strong> \\(Y\\)，把 Kleene 递归定理写成 β 等式 \\(YF = F(YF)\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>绑定器让语法有环境。Schönfinkel–Curry：闭项可译成 \\(S,K\\) 的应用，\\(I=SKK\\)。\\(Kxy=x\\)，\\(Sxyz=xz(yz)\\)。图灵完全性保留。不动点：对任意 \\(F\\)，要 \\(X\\) 使 \\(X=FX\\)。\\(Y\\) 满足 \\(YF\\to F(YF)\\)。于是递归定义 \\(F=\\lambda r.\\cdots r\\cdots\\) 变成 \\(YF\\)。这与 TM 侧递归定理同一现象，对象是项不是编码。</p><p>\\(\\Omega\\) 是 \\(Y\\) 作用在「忽略参数循环」上的亲戚；有不动点不等于有范式。</p><p><span class="marginnote">组合子就是「不引用任何外部自由变量的函数」：它需要的一切都在自己肚子里，像自带的乐高块，可以任意拼装。最经典的两块是 \\(K\\) 与 \\(S\\)：\\(Kxy\\) 返回 \\(x\\)（扔掉 \\(y\\)），\\(Sxyz\\) 相当于 \\(xz(yz)\\)。仅这两块就能拼出全部函数。</span></p><h3 id="不是最小不动点定理" tabindex="-1">\\(Y\\) 不是最小不动点定理 <a class="header-anchor" href="#不是最小不动点定理" aria-label="Permalink to &quot;$Y$ 不是最小不动点定理&quot;">​</a></h3><p>Knaster–Tarski 在格上谈最小不动点，是后课验证。这里 \\(Y\\) 只保证 β 等式，不管「最小」、不管语义域。Scott 域把二者接起来，本课不进。</p><p><span class="marginnote">Curry 的组合逻辑。Turing 也有不动点组合子 \\(\\Theta\\)。Barendregt 第 6 章。实现里的 <code>letrec</code> 是编译器的回边，语义上相当于 \\(Y\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>验证 \\(YF = F(YF)\\) 的两步 β。用 \\(Y\\) 写阶乘： \\(F=\\lambda r.\\lambda n.\\mathrm{if}n0\\,1\\,(n\\cdot r(n-1))\\)，\\(YF\\) 为阶乘项。指出无类型才能把 \\(r\\) 当函数又当值；\\(Y\\) 在简单类型里不可类型化（后课）。</p><p><span class="marginnote">不动点的直觉：函数 \\(F\\) 的不动点是被它映射回自身的值，即 \\(X=FX\\)——比如 \\(f(x)=x^2\\) 的不动点是 0 和 1。\\(Y\\) 组合子的本事是：对任何 \\(F\\) 都能现场造出这样一个 \\(X\\)，于是「自己调用自己」变成「\\(Y\\) 把自己喂给 \\(F\\)」，递归不再需要给函数起名字。</span></p>',13)),(t(),i(E,null,{default:e(()=>[s(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAM%5B%22%CE%BB%20%E9%97%AD%E9%A1%B9%22%5D%20--%3E%20SK%5B%22S%20K%20%E5%9F%BA%E5%BA%95%22%5D%0A%20%20F%5B%22%E4%BB%BB%E6%84%8F%20F%22%5D%20--%3E%20Y%5B%22Y%20F%22%5D%0A%20%20Y%20--%3E%20EQ%5B%22%3D%20F(Y%20F)%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,"不要把 \\(S,K\\) 当成优化过的指令集：它们极小，项会膨胀。用处是理论基底，不是虚拟机。",-1)),a[4]||(a[4]=r("h2",{id:"机制",tabindex:"-1"},[n("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=r("p",null,"可计算性单元到此：TM、λ、组合子同一类。自指有两种写法——编码上的 Kleene 与项上的 \\(Y\\)。下一单元加钟：时间层级。本课不开始数步。",-1)),(t(),i(E,null,{default:e(()=>[s(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%22%E9%80%92%E5%BD%92%E5%AE%9A%E4%B9%89%20F%22%5D%20--%3E%20YF%5B%22%E5%86%99%E6%88%90%20Y%20F%22%5D%0A%20%20YF%20--%3E%20R1%5B%22%CE%B2%20%E7%BA%A6%E4%B8%80%E6%AD%A5%3A%20F%20%E5%BA%94%E7%94%A8%E5%88%B0%20Y%20F%22%5D%0A%20%20R1%20--%3E%20R2%5B%22%E5%86%8D%E5%B1%95%E5%BC%80%E4%B8%80%E5%B1%82%3A%20F%20%E5%BA%94%E7%94%A8%E5%88%B0%20F%20%E7%9A%84%20Y%20F%22%5D%0A%20%20R2%20--%3E%20CHK%7B%22F%20%E5%85%88%E5%88%A4%E6%96%AD%E8%BF%98%E6%98%AF%E5%85%88%E9%80%92%E5%BD%92%22%7D%0A%20%20CHK%20--%3E%7C%22%E5%85%88%E5%88%A4%E6%96%AD%22%7C%20RES%5B%22%E9%80%90%E5%B1%82%E8%BF%94%E5%9B%9E%2C%20%E6%9C%89%E8%8C%83%E5%BC%8F%22%5D%0A%20%20CHK%20--%3E%7C%22%E6%97%A0%E8%A7%86%E5%8F%82%E6%95%B0%22%7C%20OMEGA%5B%22%E6%97%A0%E9%99%90%E8%87%AA%E5%BE%AA%E7%8E%AF%2C%20%E5%A6%82%20%CE%A9%20%E5%8F%91%E6%95%A3%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">常见误区：初学者容易以为 \\(YF\\) 一定能算出结果。实际上 \\(Y\\) 自身没有范式（约简永不停），\\(YF\\) 能否得到答案取决于 \\(F\\) 拿到参数后是否「先做终止判断再递归」；若 \\(F\\) 无视参数直接自循环，得到的就是发散的 \\(\\Omega\\)。</span></p><p>组合逻辑等式理论不可判定（与 λ 相同）。Rice 的精神平移：非平凡的外延性质对项编码不可判定。</p><p>\\(Y\\) 本身无范式，\\(YF\\) 是否有范式取决于 \\(F\\)。Turing 的 \\(\\Theta\\) 满足 \\(\\Theta F \\to F(\\Theta F)\\) 且约化更「eager」。组合逻辑的等式理论不可判定，与 λ 相同。可计算性单元到此：三种语法、一个类。下一单元给同一台 TM 加上步数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 \\(B,C,W\\) 基底变体全文，不谈线性逻辑组合子。不把 \\(Y\\) 写成 Python 装饰器教程。后课默认：递归 = 某不动点组合子；可计算模型在无类型 λ / TM 间可换。下一课时间层级定理。</p><p>可计算性课序在此封口：TM、λ、组合子同一类，自指有编码版与项版。下一单元开始数步数与格子，对象还是这些机器，只是多了资源。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(S,K\\) 生成组合子逻辑，与闭 λ 项同等力。</li><li>\\(YF=F(YF)\\)：递归是不动点，不是特殊语法。</li><li>有等式不等于有范式。</li><li>出处：Curry；Schönfinkel；Barendregt。</li></ul>',8))])}const b=d(A,[["render",B]]);export{x as __pageData,b as default};
